excels.excel:

EXPORT WITH SHEET="员工请假申请汇总表", HEADER=true,
    MAPPING={"a":"工号","b":"姓名","c":"部门","d":"请假类型","e":"开始日期","f":"结束日期","g":"请假天数","h":"审批状态"},
    FORMAT={"e":"yyyy-MM-dd","f":"yyyy-MM-dd","g":"0"},
    FORMULAS={
        G8:'SUM(G2:G7)'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    }
